CREATE TABLE "searches" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "query" text NOT NULL,
  "started_depth" text NOT NULL,
  "ended_depth" text,
  "status" text NOT NULL,
  "started_at" bigint NOT NULL,
  "finished_at" bigint,
  "document" text,
  "asker_id" bigint,
  "options" text,
  "title" text,
  "topic" text,
  "keywords" text,
  "rule" text,
  "documented" bigint,
  "kind" text,
  "author" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE TABLE "search_findings" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "search_id" bigint NOT NULL,
  "run_id" bigint,
  "branch" text,
  "place" bigint NOT NULL,
  "text" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE TABLE "search_sources" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "search_id" bigint NOT NULL,
  "finding_id" bigint,
  "url" text NOT NULL,
  "title" text,
  "supports" text,
  "mark" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);
CREATE TABLE "search_images" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "search_id" bigint NOT NULL,
  "url" text NOT NULL,
  "path" text NOT NULL,
  "type" text NOT NULL,
  "bytes" bigint NOT NULL,
  "kept_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id"),
  UNIQUE ("search_id", "url")
);
CREATE TABLE "archive_attachments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "search_id" bigint NOT NULL,
  "media" text NOT NULL,
  "url" text,
  "path" text NOT NULL,
  "type" text NOT NULL,
  "bytes" bigint NOT NULL,
  "name" text NOT NULL,
  "place" bigint,
  "kept_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id"),
  UNIQUE ("search_id", "path")
);
CREATE TABLE "web_search_shares" (
  "share_token" text,
  "search_id" bigint NOT NULL,
  "created_by" text NOT NULL,
  "created_at" bigint NOT NULL,
  "expires_at" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("share_token"),
  UNIQUE ("search_id")
);
ALTER TABLE "web_search_shares" ADD COLUMN "user_id" bigint;
CREATE INDEX "archive_attachments_search" ON "archive_attachments" (search_id);
CREATE INDEX "search_findings_place" ON "search_findings" (search_id, place);
CREATE INDEX "search_images_search" ON "search_images" (search_id);
CREATE INDEX "search_sources_finding" ON "search_sources" (search_id, finding_id);
